let gods=[{name:"Ebisu",description:"Deus da prosperidade e da pesca.",image:"assets/images/Ebisu.jpg"},{name:"Daikokuten",description:"Deus da riqueza e da colheita.",image:"assets/images/Daikokuten.jpg"},{name:"Bishamonten",description:"Deus da guerra e protetor da justiça.",image:"assets/images/Bishamonten.jpg"},{name:"Benzaiten",description:"Deusa da arte e do conhecimento.",image:"assets/images/Benzaiten.jpg"},{name:"Fukurokuju",description:"Deus da longevidade e da sabedoria.",image:"assets/images/Fukurokuju.jpg"},{name:"Hotei",description:"Deus da felicidade e da abundância.",image:"assets/images/Hotei.jpg"},{name:"Jurōjin",description:"Deus da longevidade e da saúde.",image:"assets/images/Jurojin.jpg"}];document.getElementById("sortButton").addEventListener("click",()=>{var e=Math.floor(Math.random()*gods.length);let a=gods[e];e=new Image;e.src=a.image,e.onload=()=>{document.getElementById("deityImage").src=a.image,document.getElementById("deityImage").hidden=!1,document.getElementById("deityName").innerText=a.name,document.getElementById("deityDescription").innerText=a.description},e.onerror=()=>{console.error("Erro ao carregar a imagem: "+a.image)}});